"""Append dated result observations without duplicating canonical projects or adoptions.
The input keeps explicit links to existing source records and source-level limitations.
"""
import json,hashlib,html,re,runpy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];DATA=ROOT/'data';POLICY=ROOT.parent/'mobility-policy-history'
def load(p):return json.loads(p.read_text())
def write(p,v):p.parent.mkdir(exist_ok=True,parents=True);p.write_text(json.dumps(v,ensure_ascii=False,separators=(',',':'))+'\n')
def build():
 d=load(DATA/'research-outcomes-20261103.json');rows=d['cases'];ids={c['id'] for c in rows};assert len(ids)==len(rows)
 index=load(DATA/'index-observations.json');prior=[r for r in index if r['id'] not in ids];assert len(prior)==76,'New baseline requires explicit reconciliation'
 timeline=load(DATA/'timeline-observations.json');prior_timeline=[e for e in timeline if e['case_id'] not in ids];assert len(prior_timeline)==150
 shard='data/details/observations/research-20261103.json';details={};new_index=[];new_events=[]
 fields=['id','aliases','agency_ids','agency_roles','layer','record_kind','title','region','municipality','codes','prefectures','years','themes','program_ids','classification','state','state_label','evidence','evidence_label','excerpt','last_event_date','counting_unit']
 for c in rows:
  assert c['record_kind']=='result_observation' and c['counting_unit']=='source_observation'
  c['years']=sorted({e['year'] for e in c['events']});c['last_event_date']=c['events'][-1]['date_label'];c['supplement_url']='../mobility-policy-history/updates/2026-11-outcomes/#'+c['slug']
  source_ids={s['source_id'] for s in c['sources']}
  for item in c['claims']+c['metrics']+c['events']:
   assert item['source_refs'] and all(s['source_id'] in source_ids for s in item['source_refs'])
  details[c['id']]=c;new_index.append({**{k:c[k] for k in fields},'detail':shard})
  new_events.extend([{**e,'record_kind':'result_observation'} for e in c['events']])
 write(ROOT/shard,details);write(DATA/'index-observations.json',prior+new_index);write(DATA/'timeline-observations.json',prior_timeline+new_events)
 summary=load(DATA/'summary.json');summary['as_of']=d['checked_at'];summary['counts'].update(observations=len(prior)+len(rows),result_observations=sum(x['record_kind']=='result_observation' for x in prior+new_index),observation_events=len(prior_timeline)+len(new_events));write(DATA/'summary.json',summary)
 p=DATA/'bootstrap.js';bootstrap=json.loads(p.read_text().split('=',1)[1].strip().rstrip(';'));bootstrap['as_of']=summary['as_of'];bootstrap['counts']=summary['counts'];p.write_text('window.MOBILITY_RESULTS_SUMMARY='+json.dumps(bootstrap,ensure_ascii=False,separators=(',',':'))+';\n')
 # Every retained canonical record and existing observation remains in its original layer.
 manifest={'checked_at':d['checked_at'],'record_kind':'result_observation','new_result_observations':len(rows),'new_observation_events':len(new_events),'canonical_projects_unchanged':summary['counts']['canonical'],'record_ids':sorted(ids),'retained_observations':len(prior),'retained_observation_events':len(prior_timeline),'counting_note':'Results compiled from public documents, not additional independent transport projects or adoptions.'}
 write(ROOT/'verification/research-outcomes-manifest.json',manifest)
 build_page(d)
 runpy.run_path(str(ROOT/'maintenance/sync_release.py'),run_name='__main__')
 return manifest

def build_page(d):
 e=lambda v:html.escape(str(v),quote=True)
 def source_links(ss):return '<ol class="sources">'+''.join(f'<li><a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{e(s["title"])} ↗</a><small>{e(s["document_date"])} ／ {e(s["locator"])}</small></li>' for s in ss)+'</ol>'
 def refs(rs):return ' '.join(f'<a class="ref" href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">原典 · {e(s.get("locator",""))} ↗</a>' for s in rs)
 def claims(cc):return ''.join(f'<section class="claim"><h3>{e(c["label"])}</h3><p>{e(c["statement"])}</p>{refs(c["source_refs"])}</section>' for c in cc)
 cases=[]
 for c in d['cases']:
  events=''.join(f'<li><time>{e(x["date_label"])}</time><div><p>{e(x["event_text"])}</p>{refs(x["source_refs"])}</div></li>' for x in c['events'])
  metrics=''.join(f'<div class="measure"><p>{e(m["name"])}{ " · 計画" if m["phase"]=="planned" else ""}</p><strong>{e(format(m["value"],",") if isinstance(m["value"],(int,float)) else m["value"])}</strong><span>{e(m["unit"])}</span><p>{e(m["period"])}</p><small>{e(m["definition"])} {e(m.get("denominator") or "")} {e(m.get("note") or "")}</small>{refs(m["source_refs"])}</div>' for m in c['metrics'])
  cases.append(f'<article class="section" id="{e(c["slug"])}"><p class="eyebrow">{e(c["region"])} / 資料の結果</p><h2>{e(c["title"])}</h2><p class="lede">{e(c["summary"])}</p><p class="status">{e(c["state_label"])}</p><h3>数字を、対象と一緒に読む。</h3><div class="metrics">{metrics}</div><h3>公募・実施・その後。</h3><ol class="timeline">{events}</ol>{claims(c["claims"])}<p class="notice"><b>読み解き（分析）</b><br>{e(c["lesson"])}</p><a class="button" href="../../../municipal-mobility-history/#observation/{e(c["id"])}">検索・年表とつながる結果記録へ ↗</a><details><summary>この地域の一次資料 {len(c["sources"])}件</summary>{source_links(c["sources"])}</details></article>')
 p=d['policy'];pc=''.join(f'<section class="claim"><h3>{e(c["label"])}</h3><p>{e(c["text"])}</p>{refs([p["sources"][i] for i in c.get("source_indices",[c["source_index"]])])}</section>' for c in p['claims'])
 pe=''.join(f'<li><time>{e(x["date"])}</time><div><h3>{e(x["title"])}</h3><p>{e(x["text"])}</p>{refs([p["sources"][i] for i in x.get("source_indices",[x["source_index"]])])}</div></li>' for x in p['events'])
 stops=[];start=0
 for b in p['route_breakdown']:
  end=start+b['value']/p['route_denominator']*100;stops.append(f'{b["color"]} {start:.5f}% {end:.5f}%');start=end
 legend=''.join(f'<li><i style="background:{x["color"]}"></i><span>{e(x["label"])}</span><b>{x["value"]}<small>ルート</small></b></li>' for x in p['route_breakdown'])
 first=(POLICY/'updates/2026-11/index.html').read_text();css=re.search(r'<style>(.*?)</style>',first,re.S).group(1)
 css+='''.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:24px 0 44px}.measure{background:#13212b;padding:20px;min-width:0;border-top:3px solid #70bfff}.measure>strong{font-size:clamp(32px,4vw,48px);font-weight:900;line-height:1.25;display:inline-block;overflow-wrap:anywhere}.measure>span{display:inline-block;font-size:14px;margin:0 0 0 6px}.measure>p{font-size:14px;margin:8px 0}.measure>small{display:block;color:#bdcbd4;font-size:12px}.ref{display:inline-block;font-size:12px;line-height:1.65;margin:8px 0;overflow-wrap:anywhere}.section{border-top:1px solid #35434d;padding:50px 0}.claim{margin:32px 0}.status{color:#ffc36c;font-weight:800}.sources small{display:block;color:#b7c4ce}.chart{display:grid;grid-template-columns:260px 1fr;gap:38px;align-items:center;background:#13212b;padding:30px;margin:30px 0}.donut{width:240px;aspect-ratio:1;border-radius:50%;display:grid;place-items:center}.donut>div{display:grid;place-content:center;text-align:center;border-radius:50%;background:#13212b;width:62%;height:62%;font-size:13px}.donut b{font-size:48px;line-height:1.15}.legend{list-style:none;padding:0;margin:0}.legend li{display:grid;grid-template-columns:12px 1fr auto;align-items:center;gap:12px;margin:14px 0}.legend i{width:12px;height:12px}.legend b{font-size:27px;white-space:nowrap}.legend small{font-size:11px;margin-left:4px}.timeline time{font-size:18px}.timeline{overflow-wrap:anywhere}details{margin:25px 0}summary{cursor:pointer;font-weight:700;padding:15px 0} @media(max-width:750px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.chart{grid-template-columns:1fr}.donut{margin:auto}}@media(max-width:420px){.metrics{grid-template-columns:1fr}.chart{padding:18px}.donut{width:min(220px,100%)}.section{padding:30px 0}}'''
 htmlpage=f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#091018"><title>実証の先で、何が変わったか｜政策と4地域の結果｜MDL</title><meta name="description" content="自動運転補助の評価から条件改訂へ。君津・三田・豊岡・大阪の終了、後継転換、運営再編を一次資料と数値の定義から詳しく追う。"><link rel="canonical" href="https://mobilitydlab.com/mobility-policy-history/updates/2026-11-outcomes/"><style>{css}</style></head><body><a class="skip" href="#main">本文へ</a><div class="wrap"><header><a class="brand" href="../../../">MOBILITY<br>DESIGN LAB.</a><a href="../../">政策史へ戻る ↗</a></header><main id="main"><div class="hero"><p class="eyebrow">RESEARCH UPDATE 02 / 2026.11.03</p><h1>実証の先で、<br><span>何が変わったか。</span></h1><p class="lede">評価が制度を変え、地域は運行を組み替える。<br>採択、実績、終了、後継を一本ずつたどる。</p><p class="muted">原典確認：2026年11月3日。数値の対象期間・単位・資料間の相違を併記。事業数や成功件数の全国集計ではありません。</p><nav class="nav" aria-label="今回の調査"><a href="#policy">自動運転補助 ↓</a>{''.join(f'<a href="#{e(c["slug"])}">{e(c["municipality"])} ↓</a>' for c in d['cases'])}</nav><p><a href="../2026-11/">第1弾：日立・GunMaaS・小松・永平寺とライドシェア制度史 ↗</a></p></div><section class="section" id="policy"><p class="eyebrow">POLICY / 自動運転社会実装推進事業</p><h2>{e(p['title'])}</h2><p class="lede">{e(p['summary'])}</p><p class="muted">{e(p['existing_note'])}</p><div class="chart"><div class="donut" style="background:conic-gradient({','.join(stops)})" role="img" aria-label="FY2024実証対象の置換予定131ルート。有人路線置換27、非置換7、実装予定なし10、未定87。"><div><b>131</b>置換予定表のルート</div></div><div><h3>未定と、実装予定なしは別。</h3><ul class="legend">{legend}</ul><p class="muted">2025年調査・FY2024実証未実施ルートを除く。131は表の合計計算値。総調査172ルートとは別の母数。</p></div></div>{refs([p['sources'][0]])}<ol class="timeline">{pe}</ol>{pc}<p class="notice"><b>37事業 ≠ 37自治体 ≠ 37稼働地点</b><br>一覧の掲載団体名は36。採択、交付決定、支払、運行開始は異なる段階です。</p><a class="button" href="../../#program/av_support">既存の制度記録と公式出典へ ↗</a><details><summary>制度の一次資料 {len(p['sources'])}件</summary>{source_links(p['sources'])}</details></section>{''.join(cases)}<section class="section"><h2>同じ数字で、順位をつけない。</h2><p>君津の月平均、三田の人／便、豊岡の輸送人員と運行回数、大阪の予約成立率。測っている対象も、提供条件も違う。利用の増減だけでなく、到達できる場所、運転者配置、費用、断られた予約と利用対象を合わせて読む。</p><p class="notice">4地域を新たな4事業として重複加算しません。既存採択・自治体履歴との関係を示した「資料の結果」として、検索・地図・年表に追加しています。</p><h3>違う対応を、同じ物差しで比較する。</h3><p>既存運行の料金・区域・時間を改善する、別の運行主体・方式へ移す、運転者と路線の役割を再配置する。3つの対応に加えて、変更しない場合に残る移動機会と負担も比較対象になる。どの地域でも同じ方策が優れるとは、この資料だけでは決められない。</p><h3>次に確かめること。</h3><p class="muted">自治体担当者・運行事業者・地域の読者が、継続や再編の判断に何が足りないかを見分けるための整理。特定地域への導入・廃止の提言ではありません。</p><ul><li><b>国の補助制度：</b>交付先の計画公表、実装条件達成、運行実績、確定費用を別々に確認する。条件改訂後の比較データが揃うまで、継続率改善・費用削減の効果は保留。</li><li><b>君津：</b>未充足の行き先・時間と代替手段を照合する。終了だけで需要がないとする説明は採用しない。</li><li><b>三田：</b>市・運行主体の本格運行後の利用、決算、対象外の人の代替移動を確認する。実証値を年間成果へ外挿しない。</li><li><b>豊岡：</b>国と市の回数・便数の定義を照合し、同一の集計と確認できた場合だけ比較を更新する。運転者配置の効果は他路線の運行維持データで検証する。</li><li><b>大阪：</b>市と事業者の区別・期間別の予約成立率、定義、費用を確認する。需要増でも成立率が下がる場合、利用人数だけによる高評価を見直す。</li></ul><p class="notice">資料照合は2026年11月3日時点。実証条件が異なるため因果効果の確定は未完了です。新たな現地実験・運行判断は実施していません。後続資料が出た際に原記載を残し、確認できた範囲だけ評価を更新します。</p><a class="button" href="../../../municipal-mobility-history/#projects?kind=result_observation">資料の結果を検索する ↗</a></section></main><footer><p>MDL RESEARCH ARCHIVE · 原典確認 2026.11.03</p><p>既存PDF・Excel・基礎集計は保持。今回の追補は本文と、検索できる結果記録に掲載しています。</p></footer></div></body></html>'''
 out=POLICY/'updates/2026-11-outcomes/index.html';out.parent.mkdir(exist_ok=True,parents=True);out.write_text(htmlpage)
if __name__=='__main__':print(json.dumps(build(),ensure_ascii=False))
